using System.Text;
using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public enum SchemeAction { Whisper, Forward, WriteLetter, ForgeLetter, VerifyLetter, ShowDenial, QueryTemple, SendScout, CaptureScout, PlanReturn, ScoutBlocked, ReportScout, ExecuteOperation, AcceptOperation }
public enum SchemeTopic { ForeignContact, SupplyConcern, ConflictingOrders, Arson, Sabotage, SeizeRice, Agitation }
public sealed record SchemeInput(EntityId Id,SchemeAction Action,EntityId Person,EntityId Subject,SchemeTopic Topic=SchemeTopic.ForeignContact,EntityId? Reference=null,EntityId? Destination=null);
public sealed record SchemeEvent(SchemeInput Input,EntityId Actor,EntityId Site,long At,long Revision,Intent? Movement,EntityId[] Sources);
public sealed record SchemeState(int Schema,string Policy,SchemeEvent[] Events);
public sealed record SchemeClaim(EntityId Id,EntityId Observer,EntityId Subject,EntityId Speaker,string Statement,long LearnedAt,EntityId Site,string Standing);
public static class InformationSchemes
{
 public const string Policy="personally-heard-claims-physical-papers-scout-v1",LandRoute="consenting-scout-physical-return-land-v1",ReportKind="physical-scout-observation-report";
 internal static SchemeEvent[] Events(ContractWorld w)=>w.Schemes?.Events??[];
 static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool c,string reason){if(!c)throw new InvalidDataException(reason);}
 internal static EntityId Id(string kind,string basis)=>new("scheme:"+kind+"/"+ContractJson.Hash(Encoding.UTF8.GetBytes(basis))[..24]);
 public static string ReportId(EntityId mission)=>Id("report",mission.Value).Value;
 internal static string? Address(ContractWorld w,MessageEnvelope message){var mission=Events(w).SingleOrDefault(e=>e.Input.Action==SchemeAction.SendScout&&ReportId(e.Input.Id)==message.Id);return mission==null?null:NewGameWorld.Node(mission.Site.Value);}
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>Events(w).Any(e=>e.Input.Id==id);
 static bool Local(ContractWorld w,EntityId a,EntityId b)=>SocialWorld.Site(w,a) is {} site&&SocialWorld.Site(w,b)==site;
 static bool Adult(ContractWorld w,EntityId p)=>w.Characters.Any(c=>c.Id==p&&c.Life==LifeState.Adult);
 public static string Statement(SchemeTopic topic)=>topic switch{SchemeTopic.ForeignContact=>"別家へ近づいているという噂",SchemeTopic.SupplyConcern=>"兵糧を心配しているという噂",_=>"指示が食い違っているという噂"};
 internal static void Add(ContractWorld w,SchemeInput input,EntityId actor,EntityId site,Intent? move=null,EntityId[]? sources=null){w.Schemes??=new(1,Policy,[]);w.Schemes=w.Schemes with{Events=[..w.Schemes.Events,new(input,actor,site,w.ElapsedSeconds,w.CommitSequence,move,sources??[])]};}
 public static SchemeClaim[] Claims(ContractWorld w,EntityId observer)
 {
  var rows=new List<SchemeClaim>();
  foreach(var e in Events(w).OrderBy(e=>e.Revision)){
   if(e.Input.Action==SchemeAction.ExecuteOperation && DestructiveSchemes.Witness(w,e,observer) is {} witness)rows.Add(witness);
   if(e.Input.Action==SchemeAction.Whisper&&e.Input.Person==observer)rows.Add(new(e.Input.Id,observer,e.Input.Subject,e.Actor,Statement(e.Input.Topic),e.At,e.Site,"未確認の伝聞。事実・違反・処分は未確定"));
   if(e.Input.Action is SchemeAction.WriteLetter or SchemeAction.ForgeLetter){foreach(var received in SocialWorld.Ledger(w).Where(r=>r.Input.Action==SocialWorldAction.ReceiveGift&&r.Actor==observer)){var gift=SocialWorld.Ledger(w).Single(g=>g.Input.Id==received.Input.Reference);if(gift.Input.Asset==e.Input.Id)rows.Add(new(e.Input.Id,observer,e.Input.Subject,e.Input.Person,Statement(e.Input.Topic),received.At,received.Site,"書状の記載。名義と真偽は未確認"));}}
   if(e.Input.Action==SchemeAction.Forward&&e.Input.Person==observer){var origin=Before(w,e.Actor,e.Input.Reference!.Value,e.Revision);if(origin!=null)rows.Add(origin with{Id=e.Input.Id,Observer=observer,Speaker=e.Actor,LearnedAt=e.At,Site=e.Site,Standing="人づての伝聞。原本は未確認"});}
   if(e.Input.Action==SchemeAction.VerifyLetter&&e.Actor==observer){var letter=Events(w).Single(p=>p.Input.Id==e.Input.Reference);bool genuine=letter.Input.Action==SchemeAction.WriteLetter;rows.Add(new(e.Input.Id,observer,letter.Input.Subject,letter.Input.Person,genuine?"名義人がこの書状を書いたと現地で確認した":"名義人がこの書状を書いていないと現地で否認した",e.At,e.Site,genuine?"本人確認。ただし書かれた内容の真実は未確定":"本人の否認。作成者・犯人は未確定"));}
   if(e.Input.Action==SchemeAction.ShowDenial&&e.Input.Person==observer){var denial=Before(w,e.Actor,e.Input.Reference!.Value,e.Revision);if(denial!=null)rows.Add(denial with{Id=e.Input.Id,Observer=observer,Speaker=e.Actor,LearnedAt=e.At,Site=e.Site,Standing="本人の照合結果を聞いた。犯人・処分は未確定"});}
  }return rows.DistinctBy(c=>c.Id).ToArray();
 }
 static SchemeClaim? Before(ContractWorld w,EntityId observer,EntityId id,long revision){var copy=w.ForkTransportLocation();if(copy.SocialWorld!=null)copy.SocialWorld=copy.SocialWorld with{Events=SocialWorld.Ledger(w).Where(e=>e.Revision<revision).ToArray()};copy.Schemes=w.Schemes! with{Events=Events(w).Where(e=>e.Revision<revision).ToArray()};return Claims(copy,observer).SingleOrDefault(c=>c.Id==id);}
 public static RelationshipFact[] Facts(ContractWorld w,EntityId observer,EntityId subject)=>Claims(w,observer).Where(c=>c.Subject==subject).GroupBy(c=>c.LearnedAt/86400).Select(g=>g.Last()).Select(c=>new RelationshipFact(observer,subject,"scheme:"+c.Id.Value,"未確認の噂・書状や照合結果を知った（処分の根拠は別）",c.LearnedAt,c.LearnedAt,0,0,0,c.Statement.Contains("否認")?0:1)).ToArray();
 internal static PersonalObject[] Documents(ContractWorld w,long revision)=>Events(w).Where(e=>e.Revision<=revision&&e.Input.Action is SchemeAction.WriteLetter or SchemeAction.ForgeLetter).Select(e=>new PersonalObject(e.Input.Id,"書状（封書・名義の確認は別）","scheme-letter",1,e.Actor,e.Actor,e.Site,null,false,["書状の実物。内容や名義は受領と照合を経て判断する"])).ToArray();
 public static void Execute(ContractWorld w,SchemeInput i,EntityId actor)
 {
  Need(NewGameWork.Enabled(w)&&Adult(w,actor)&&Enum.IsDefined(i.Action)&&Enum.IsDefined(i.Topic),"扱えない情報です");var site=SocialWorld.Site(w,actor);Need(site!=null,"現地へ到着してください");
  Need(i.Action is not(SchemeAction.AcceptOperation or SchemeAction.CaptureScout or SchemeAction.PlanReturn or SchemeAction.ScoutBlocked or SchemeAction.ReportScout),"密偵の結果は実際の行程から確定します");
  if(i.Action==SchemeAction.ExecuteOperation){Need(i.Reference==null&&i.Destination==null,"本人の現地実行を指定してください");DestructiveSchemes.Check(w,i,actor,site.Value,w.ElapsedSeconds,w.CommitSequence);Add(w,i,actor,site.Value);return;}
  Need(!DestructiveSchemes.Operation(i.Topic)||i.Action==SchemeAction.SendScout,"計略の入力先が違います");
  if(i.Action==SchemeAction.SendScout){if(DestructiveSchemes.Operation(i.Topic))Need(CastleSiege.Enabled(w)&&i.Destination is {} target&&target!=site&&MaterialMarkets.Sites(w).Contains(target),"計略の対象拠点を指定してください");Need(i.Person!=actor&&SocialWorld.CarrierChoices(w,actor).Contains(i.Person)&&!Busy(w,i.Person,w.ElapsedSeconds,w.CommitSequence+1)&&i.Destination!=null,"同意した、空いている現地の同行者と行先を指定してください");if(DestructiveSchemes.Operation(i.Topic)){
    Need(DestructiveSchemes.Accepts(w,i,w.ElapsedSeconds,w.CommitSequence),"同行者は今回の計略を断りました");
    Add(w,new(Id("accepted",i.Id.Value),SchemeAction.AcceptOperation,actor,i.Destination!.Value,i.Topic,Reference:i.Id),i.Person,site.Value);
   }var move=TravelWorld.ActorMove(w,Id("outward",i.Id.Value).Value,i.Person,NewGameWorld.Node(i.Destination!.Value.Value),true,LandRoute);Add(w,i,actor,site.Value,move);return;}
  if(i.Action is SchemeAction.Whisper or SchemeAction.Forward or SchemeAction.ShowDenial)Need(i.Person!=actor&&Adult(w,i.Person)&&Local(w,actor,i.Person),"相手と現地で会ってください");
  if(i.Action==SchemeAction.Whisper){Need(Adult(w,i.Subject)&&(Local(w,actor,i.Subject)||SocialWorld.Facts(w,actor,i.Subject).Length>0),"本人が知っている人物だけを話題にしてください");Need(!Events(w).Any(e=>e.Actor==actor&&e.Input.Action==i.Action&&e.Input.Subject==i.Subject&&e.Input.Person==i.Person&&e.At/86400==w.ElapsedSeconds/86400),"同じ相手に今日は既に話しました");}
  else if(i.Action is SchemeAction.Forward or SchemeAction.ShowDenial){Need(i.Reference!=null&&Claims(w,actor).Any(c=>c.Id==i.Reference),"まだ聞いていない情報です");if(i.Action==SchemeAction.ShowDenial)Need(Events(w).Any(e=>e.Input.Id==i.Reference&&e.Input.Action==SchemeAction.VerifyLetter&&e.Actor==actor),"自分が得た本人の照合結果を示してください");Need(!Events(w).Any(e=>e.Actor==actor&&e.Input.Person==i.Person&&e.Input.Reference==i.Reference&&e.Input.Action==i.Action),"同じ情報は伝達済みです");}
  else if(i.Action is SchemeAction.WriteLetter or SchemeAction.ForgeLetter){Need(Adult(w,i.Subject)&&Adult(w,i.Person)&&i.Reference==null,"書状の名義と話題の人物を指定してください");Need(i.Action==SchemeAction.WriteLetter?i.Person==actor:i.Person!=actor&&(Local(w,actor,i.Person)||SocialWorld.Facts(w,actor,i.Person).Length>0),"本人が知る名義だけを指定してください");}
  else if(i.Action==SchemeAction.VerifyLetter){Need(i.Reference!=null&&SocialAssets.Inventory(w,actor).Any(o=>o.Id==i.Reference&&o.Kind=="scheme-letter"),"書状の実物を持参してください");var paper=Events(w).Single(e=>e.Input.Id==i.Reference);Need(i.Person==paper.Input.Person&&Local(w,actor,i.Person),"名義人に現地で照合を頼んでください");}
  else if(i.Action==SchemeAction.QueryTemple){var temple=SocialWorld.Temple(w,site.Value);Need(i.Person==temple.Representative,"現地の寺社代表に聞いてください");Need(!Events(w).Any(e=>e.Actor==actor&&e.Input.Action==i.Action&&e.Site==site&&e.At/86400==w.ElapsedSeconds/86400),"今日は既に寺社に尋ねました");var sources=SocialWorld.Renown(w,temple.Representative).Where(f=>f.LearnedAt<=w.ElapsedSeconds&&f.Region==site).Select(f=>new EntityId(f.Id)).ToArray();Add(w,i,actor,site.Value,sources:sources);return;}
  Add(w,i,actor,site.Value);
 }
 public static RenownFact[] TempleKnowledge(ContractWorld w,EntityId observer){var queries=Events(w).Where(e=>e.Actor==observer&&e.Input.Action==SchemeAction.QueryTemple).ToArray();if(queries.Length==0)return [];return queries.SelectMany(e=>SocialWorld.Renown(w,SocialWorld.Temple(w,e.Site).Representative).Where(f=>e.Sources.Any(s=>s.Value==f.Id)&&f.LearnedAt<=e.At).Select(f=>f with{Observer=observer,LearnedAt=e.At,Source=e.Input.Id.Value})).DistinctBy(f=>f.Id).ToArray();}
 internal static bool IsTrip(ContractWorld w,Intent i)=>Events(w).Any(e=>e.Movement==i);
 internal static void ValidateTrip(ContractWorld w,Intent i){var e=Events(w).SingleOrDefault(e=>e.Movement==i);Need(e!=null&&i.RoutePolicy==LandRoute&&i.Actor==i.Executor,"密偵の署名した移動原本がありません");var mission=e.Input.Action==SchemeAction.SendScout?e:Events(w).Single(m=>m.Input.Id==e.Input.Reference);Need(i.Actor==mission.Input.Person&&i.DestinationSite==(e.Input.Action==SchemeAction.SendScout?mission.Input.Destination:mission.Site),"密偵の引受原本と違う行先です");}
 internal static bool Busy(ContractWorld w,EntityId actor,long at,long revision)=>Events(w).Any(e=>e.Input.Action==SchemeAction.SendScout&&e.Input.Person==actor&&(e.At<at||e.At==at&&e.Revision<revision)&&!Events(w).Any(r=>r.Input.Reference==e.Input.Id&&r.Input.Action==SchemeAction.ReportScout&&(r.At<at||r.At==at&&r.Revision<revision)));
 internal static void Tick(ContractWorld w,bool clockAdvanced=false)
 {
  if(w.Schemes==null)return;
  foreach(var task in w.Tasks.Where(t=>t.Execution is ExecutionPhase.Failed or ExecutionPhase.Stopped&&w.Requests.Single(r=>r.Id==t.RequestId).Intent.RoutePolicy==LandRoute)){
   if(w.Locations.Single(l=>l.Actor==task.Executor).Route!=WorldSession.Child("route",task.Id,"graph"))continue;var actual=BranchRoutes.Location(w,task);if(actual.Kind==LocationKind.AtSite)w.Locations=w.Locations.Select(l=>l.Actor==task.Executor?actual:l).ToArray();
  }
  if(clockAdvanced&&w.ElapsedSeconds%86400==0){foreach(var actor in w.Characters.Where(c=>c.Id!=w.PlayerControl&&c.Life==LifeState.Adult).Select(c=>c.Id).OrderBy(c=>c.Value,StringComparer.Ordinal)){
   var source=Claims(w,actor).FirstOrDefault(c=>c.LearnedAt<w.ElapsedSeconds);if(source==null)continue;var listener=w.Characters.Where(c=>c.Life==LifeState.Adult&&c.Id!=actor&&c.Id!=source.Subject&&Local(w,actor,c.Id)&&!Claims(w,c.Id).Any(x=>x.Subject==source.Subject&&x.Statement==source.Statement)).Select(c=>c.Id).OrderBy(c=>c.Value,StringComparer.Ordinal).FirstOrDefault();if(listener.Value==null)continue;
   var id=Id("npc-hearsay",actor.Value+"/"+w.ElapsedSeconds/86400);if(!OwnIdUsed(w,id))Execute(w,new(id,SchemeAction.Forward,listener,source.Subject,Reference:source.Id),actor);
  }}
  foreach(var paper in SocialAssets.Objects(w).Where(o=>o.Kind=="scheme-letter"&&o.Holder!=w.PlayerControl&&o.Gift==null&&!o.Consumed)){
   var source=Events(w).Single(e=>e.Input.Id==paper.Id);if(source.Input.Person!=paper.Holder||!Adult(w,paper.Holder)||SocialWorld.Site(w,paper.Holder)==null)continue;var id=Id("npc-authorship",paper.Id.Value+"/"+paper.Holder.Value);if(!OwnIdUsed(w,id))Execute(w,new(id,SchemeAction.VerifyLetter,paper.Holder,source.Input.Subject,Reference:paper.Id),paper.Holder);
  }
  foreach(var mission in Events(w).Where(e=>e.Input.Action==SchemeAction.SendScout).ToArray()){
   var task=w.Tasks.SingleOrDefault(t=>t.RequestId==mission.Movement!.RequestId);if(task?.Execution is not(ExecutionPhase.Completed or ExecutionPhase.Failed or ExecutionPhase.Stopped)&&!Events(w).Any(e=>e.Input.Reference==mission.Input.Id&&e.Input.Action==SchemeAction.ScoutBlocked))continue;var agent=mission.Input.Person;var site=SocialWorld.Site(w,agent);if(site==null)continue;
   var captured=Events(w).SingleOrDefault(e=>e.Input.Reference==mission.Input.Id&&e.Input.Action==SchemeAction.CaptureScout);
   if(captured==null&&DestructiveSchemes.Operation(mission.Input.Topic)){
    var source=DestructiveSchemes.Observe(w,mission,site.Value,task?.Execution==ExecutionPhase.Completed&&site==mission.Input.Destination);
    Add(w,new(Id("capture",mission.Input.Id.Value),SchemeAction.CaptureScout,agent,agent,Reference:mission.Input.Id),agent,site.Value,sources:[source]);
   }else if(captured==null){if(task?.Execution==ExecutionPhase.Completed&&site==mission.Input.Destination){foreach(var road in BranchRoutes.GraphEdges(w).Where(e=>!NationalRoutes.Sea(e.Id)&&(RegionalCampaign.Site(e.From)==site||RegionalCampaign.Site(e.To)==site)))RegionalCampaign.InspectRoad(w,agent,road.Id);}var sources=w.Evidence.Where(e=>e.Observer==agent&&e.Message==null&&e.RecordedAt>=mission.At&&w.Knowledge.Any(k=>k.Character==agent&&k.Evidence==e.Id)&&(e.Claim.StartsWith("route-open:",StringComparison.Ordinal)||e.Claim.StartsWith("route-block:",StringComparison.Ordinal))).Select(e=>e.Id).ToArray();Add(w,new(Id("capture",mission.Input.Id.Value),SchemeAction.CaptureScout,agent,agent,Reference:mission.Input.Id),agent,site.Value,sources:sources);}
   if(site==mission.Site&&Local(w,agent,mission.Actor)&&!Events(w).Any(e=>e.Input.Reference==mission.Input.Id&&e.Input.Action==SchemeAction.ReportScout)){
    captured=Events(w).Single(e=>e.Input.Reference==mission.Input.Id&&e.Input.Action==SchemeAction.CaptureScout);string id=ReportId(mission.Input.Id);var facts=captured.Sources.Select(source=>{var e=w.Evidence.Single(e=>e.Id==source);return new InformationFact(e.Id,e.Claim,e.ObservedAt!.Value);}).ToArray();var payload=new InformationPayload(mission.Input.Id,agent,facts);MessageFlow.Send(w.Messaging,new(id,mission.Input.Id.Value,ReportKind,agent.Value,mission.Actor.Value,Encoding.UTF8.GetString(ContractJson.Write(payload)),mission.Site.Value,w.ElapsedSeconds),w.ElapsedSeconds,1);w.SealedMessages=[..w.SealedMessages,new(id)];RegionalCampaign.Bind(w);Add(w,new(Id("reported",mission.Input.Id.Value),SchemeAction.ReportScout,mission.Actor,agent,Reference:mission.Input.Id),agent,site.Value);
   }
  }
  foreach(var mission in Events(w).Where(e=>e.Input.Action==SchemeAction.SendScout)){
   string message=ReportId(mission.Input.Id);if(!MessageFlow.Knows(w.Messaging,message,mission.Actor.Value))continue;var report=w.Messaging.Messages.Single(m=>m.Id==message);var payload=ContractJson.Read<InformationPayload>(Encoding.UTF8.GetBytes(report.Body));foreach(var fact in payload.Facts){var id=Id("received-evidence",message+"/"+fact.Source.Value);if(w.Evidence.Any(e=>e.Id==id))continue;w.Evidence=[..w.Evidence,new(id,mission.Actor,mission.Input.Person,fact.Claim,fact.ObservedAt,w.ElapsedSeconds,new(message),null)];w.Knowledge=[..w.Knowledge,new(mission.Actor,id,w.ElapsedSeconds)];}
  }
 }
 internal static bool IsSourceReport(ContractWorld w,Evidence evidence){if(evidence.Message==null)return false;var mission=Events(w).SingleOrDefault(e=>e.Input.Action==SchemeAction.SendScout&&ReportId(e.Input.Id)==evidence.Message.Value.Value&&e.Actor==evidence.Observer);if(mission==null||!MessageFlow.Knows(w.Messaging,evidence.Message.Value.Value,evidence.Observer.Value))return false;var capture=Events(w).Single(e=>e.Input.Reference==mission.Input.Id&&e.Input.Action==SchemeAction.CaptureScout);return capture.Sources.Any(id=>w.Evidence.Any(source=>source.Id==id&&source.Observer==mission.Input.Person&&source.Claim==evidence.Claim&&source.ObservedAt==evidence.ObservedAt)&&evidence.Id==Id("received-evidence",evidence.Message.Value.Value+"/"+id.Value));}
 internal static long? NextBoundary(ContractWorld w,long target)=>w.Schemes!=null&&(w.ElapsedSeconds/86400+1)*86400<=target?(w.ElapsedSeconds/86400+1)*86400:null;
 internal static void Rewind(ContractWorld w,long at,long revision){if(w.Schemes!=null){var es=Events(w).Where(e=>e.At<at||e.At==at&&e.Revision<=revision).ToArray();w.Schemes=es.Length==0?null:w.Schemes with{Events=es};}}
 public static void Validate(ContractWorld w,ContractWorld? prior)
 {
  if(w.Schemes==null){Need(prior?.Schemes==null,"情報の記録が消えています");return;}Need(NewGameWork.Enabled(w)&&w.Schemes.Schema==1&&w.Schemes.Policy==Policy,"情報の版が不正です");var es=Events(w);Need(es.Select(e=>e.Input.Id).Distinct().Count()==es.Length&&es.All(e=>Enum.IsDefined(e.Input.Action)&&Enum.IsDefined(e.Input.Topic)&&e.At<=w.ElapsedSeconds&&e.At>=0&&e.Revision<=w.CommitSequence&&e.Revision>0&&w.Characters.Any(c=>c.Id==e.Actor)&&e.Sources!=null),"情報の原本が不正です");if(prior?.Schemes!=null)Need(ContractJson.CanonicalHash(es.Take(prior.Schemes.Events.Length).ToArray())==ContractJson.CanonicalHash(prior.Schemes.Events),"過去の情報が書き換わりました");
  foreach(var e in es){if(e.Input.Action==SchemeAction.ExecuteOperation)DestructiveSchemes.Check(w,e.Input,e.Actor,e.Site,e.At,e.Revision);if(e.Movement!=null)ValidateTrip(w,e.Movement);if(e.Input.Action is SchemeAction.Forward or SchemeAction.ShowDenial)Need(e.Input.Reference!=null&&Before(w,e.Actor,e.Input.Reference.Value,e.Revision)!=null,"未知の伝聞です");if(e.Input.Action==SchemeAction.CaptureScout)Need(e.Sources.All(id=>w.Evidence.Any(source=>source.Id==id&&source.Observer==e.Actor&&source.Message==null&&source.RecordedAt<=e.At)),"他人や未来の観測を取得しています");}
  foreach(var mission in es.Where(e=>e.Input.Action==SchemeAction.SendScout)){Need(mission.Actor==w.PlayerControl&&w.Companions?.Orders.Where(q=>q.Input.Person==mission.Input.Person&&(q.At<mission.At||q.At==mission.At&&q.Revision<mission.Revision)&&q.Input.Action is CompanionAction.Agree or CompanionAction.EndAgreement).OrderBy(q=>q.Revision).LastOrDefault()?.Input.Action==CompanionAction.Agree,"密偵の事前同意がありません");}
  foreach(var mission in es.Where(e=>e.Input.Action==SchemeAction.SendScout&&DestructiveSchemes.Operation(e.Input.Topic))){
   var assent=es.SingleOrDefault(e=>e.Input.Action==SchemeAction.AcceptOperation&&e.Input.Reference==mission.Input.Id);
   Need(DestructiveSchemes.Accepts(w,mission.Input,mission.At,mission.Revision)&&assent!=null&&assent.Actor==mission.Input.Person&&assent.Site==mission.Site&&assent.Input.Subject==mission.Input.Destination&&assent.Input.Person==mission.Actor&&assent.Input.Topic==mission.Input.Topic&&assent.Revision==mission.Revision,"計略を引き受けた本人・場所・用件の一致が必要です");
  }
  foreach(var captured in es.Where(e=>e.Input.Action==SchemeAction.CaptureScout)){var mission=es.Single(e=>e.Input.Id==captured.Input.Reference&&e.Input.Action==SchemeAction.SendScout);if(DestructiveSchemes.Operation(mission.Input.Topic))DestructiveSchemes.ValidateObservation(w,mission,captured);Need(captured.Actor==mission.Input.Person&&captured.Sources.All(id=>w.Evidence.Any(source=>source.Id==id&&source.RecordedAt>=mission.At&&(DestructiveSchemes.Operation(mission.Input.Topic)&&id==Id("operation-observation",mission.Input.Id.Value)||source.Claim.StartsWith("route-open:",StringComparison.Ordinal)||source.Claim.StartsWith("route-block:",StringComparison.Ordinal)))),"密偵の観測範囲が違います");}
  foreach(var report in es.Where(e=>e.Input.Action==SchemeAction.ReportScout)){var mission=es.Single(m=>m.Input.Id==report.Input.Reference&&m.Input.Action==SchemeAction.SendScout);Need(report.Actor==mission.Input.Person&&report.Site==mission.Site&&TransportWork.At(w,mission.Actor,mission.Site,report.At,report.Revision,stableCompletion:true)&&TransportWork.At(w,mission.Input.Person,mission.Site,report.At,report.Revision,stableCompletion:true),"物理帰還前の密偵返報です");var message=w.Messaging.Messages.Single(m=>m.Id==ReportId(mission.Input.Id));var capture=es.Single(c=>c.Input.Reference==mission.Input.Id&&c.Input.Action==SchemeAction.CaptureScout);var payload=ContractJson.Read<InformationPayload>(Encoding.UTF8.GetBytes(message.Body));Need(payload.Speaker==mission.Input.Person&&payload.Quote==mission.Input.Id&&payload.Facts.Select(f=>f.Source).SequenceEqual(capture.Sources)&&payload.Facts.All(f=>w.Evidence.Any(s=>s.Id==f.Source&&s.Claim==f.Claim&&s.ObservedAt==f.ObservedAt)),"密偵の返報が観測原本と違います");}
 }
}
public sealed partial class WorldSession
